"""E1 FC display stock: every item of the delivery's placement layer, as Python-owned poses."""

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class RetailStockPlacement:
    """One display-stock item: which group and authored prim it came from, which SKU, where."""

    group: str
    source_prim_name: str
    sku: str
    position_xyz: tuple[float, float, float]
    rotation_xyzw: tuple[float, float, float, float]

    @property
    def instance_name(self) -> str:
        return f"fc_stock_{self.group.lower()}_{self.source_prim_name.lower()}"


